"""Assemble each bridge from the common core and one adapter.

Why this module exists
An application loads one file, while the protocol and security code must exist
only once. This script joins bridges/_core.py and bridges/adapters/<name>.py into
bridges/generated/<name>_bridge.py, so that the copies can never drift apart.

Usage: python3 scripts/build_bridges.py [--check]
"""

import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

HEADER = (
    "# Generated by scripts/build_bridges.py from bridges/_core.py and bridges/adapters/{name}.py.\n"
    "# Do not edit: change those files and run python3 scripts/build_bridges.py.\n"
    "# Holds no token: the bridge reads it from LIBREMODULAR_TOKEN_PATH or the default path.\n"
    "\n"
)

FOOTER = (
    "\n"
    "# --- entry point, added by scripts/build_bridges.py ---------------------------\n"
    "\n"
    "launch(ADAPTER(), DEFAULT_PORT)\n"
)

SEPARATOR = "\n# --- adapter: bridges/adapters/{name}.py ---------------------------------------\n\n"


def render(name, core_text, adapter_text):
    """The text of the generated bridge of adapter `name`."""
    return (
        HEADER.format(name=name)
        + core_text.rstrip("\n")
        + "\n"
        + SEPARATOR.format(name=name)
        + adapter_text.rstrip("\n")
        + "\n"
        + FOOTER
    )


def adapters(root):
    """The adapter names, in a stable order."""
    folder = root / "bridges" / "adapters"
    return sorted(path.stem for path in folder.glob("*.py") if not path.stem.startswith("_"))


def build(root, check_only=False):
    """Write every generated bridge whose text changed; return the changed paths.
    With `check_only`, nothing is written."""
    core_text = (root / "bridges" / "_core.py").read_text(encoding="utf-8")
    generated = root / "bridges" / "generated"
    changed = []
    for name in adapters(root):
        adapter_text = (root / "bridges" / "adapters" / (name + ".py")).read_text(
            encoding="utf-8"
        )
        text = render(name, core_text, adapter_text)
        target = generated / (name + "_bridge.py")
        current = target.read_text(encoding="utf-8") if target.exists() else None
        if current == text:
            continue
        changed.append(target)
        if not check_only:
            generated.mkdir(exist_ok=True)
            with open(target, "w", encoding="utf-8", newline="\n") as handle:
                handle.write(text)
    return changed


def main(arguments):
    check_only = arguments == ["--check"]
    if arguments and not check_only:
        sys.stderr.write("usage: python3 scripts/build_bridges.py [--check]\n")
        return 2
    changed = build(ROOT, check_only)
    for path in changed:
        verb = "out of date" if check_only else "written"
        sys.stderr.write("%s: %s\n" % (verb, path.relative_to(ROOT)))
    return 1 if check_only and changed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
